#[test]
fn rf_invariance() {
    lane(
        "RF-INVARIANCE",
        Pin {
            cases: 25,
            tally: tally(7096, 7056, 0, 40),
            outcomes: (25, 0, 0),
            discriminated: 47,
            non_discriminating: 7,
            input_derived_not_covered: &[],
        },
    );

//! RF-INVARIANCE's recorded observations (plan Q7; ROOT: recorded, not
//! asserted). The gate compares each variant with its own R1 expectations.
//! Beside it, each variant's published values are set against its BASE's,
//! mapped by the variant's transform:
//! - OFF (offsets 1e3 and 1e6): every quantity unchanged;
//! - ROT (Q3, Q9): the vectors u, θ, R and S rotate by Q; N, T, Mb, tw and
//!   ext are unchanged;
//! - RELABEL: nodes and members renamed, member directions reversed, so
//!   Mb.i ↔ Mb.j; everything else unchanged;
//! - UNITS-mm: lengths, moments and extensions ×1,000; forces, rotations and
//!   twists unchanged.
//!
//! Each observation is the largest |variant − mapped BASE| in units of the
//! variant's predicate allowance 1e-9·max(|exp|, scale), formed in binary64
//! for display (never a decision), and the number of rows whose bits are
//! identical where the map is the identity (OFF, RELABEL). Nodes are matched
//! by coordinates, members by their end nodes.

    let scales = floor::scales(case, model);
    for row in &case.rows {
        let exp = Exact::parse_decimal(&row.expected).unwrap();
        let scale = Exact::parse_decimal(case.scale_of(row)).unwrap();
        let covered = exact::covered(&exp, &scale, floor::row_scale(row, &scales));
        let verdict = match model.resolve(&row.key) {
            Ok(target) => {
                let v = judge(&observe(target, &published, model), &exp, &scale, covered);
                if !covered {
                    not_covered.push(row.key.clone());
                    for id in sources(target) {
                        let restrained = matches!(id, QuantityId::Displacement(d)
                            if model.constraints.contains(&(d.node, d.component.index())));
                        match published.get(&id).map(|r| &r.class) {
                            Some(RowClass::AbsoluteVerified { .. })
                            | Some(RowClass::Unpublishable) => {}
                            Some(RowClass::InputDerived) if restrained => {
                                input_derived_not_covered
                                    .push(format!("{}:{}", case.id, row.key))
                            }
                            other => class_mismatches.push(format!(
                                "{}: {} ({id:?} is {other:?})",
                                case.id, row.key
                            )),
                        }
                    }
                }
                v
            }
            Err(e) => Verdict::Fail(e),
        };
        if let Verdict::Fail(why) = &verdict {
            failures.push(format!("{}: {} ({}) {why}", case.id, row.key, row.expected));
        }
        tally.add(&verdict);
    }
} else if listed && matches!(outcome, CaseOutcome::Unresolved { .. }) {
    for _row in &case.rows {
        tally.add(&Verdict::ExpectedUnresolved);
    }
} else {
    for _row in &case.rows {
        tally.add(&Verdict::Fail(format!("case {label}")));
    }
    failures.push(format!(
        "{}: not selected: {}",
        case.id,
        records::outcome_text(&outcome)
    ));
}
